import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cute_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cute_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Kernel: C = A * B
// A: (M,K) row-major, stride (K,1)
// B: (K,N) row-major, viewed as (N,K) with stride (1,N)  [i.e. B^T view]
// C: (M,N) row-major, stride (N,1)
template <class ProblemShape,
          class TA, class StrideA,
          class TB, class StrideB,
          class TC, class StrideC>
__global__ static void
gemm_device(ProblemShape shape_MNK,
            TA const* A, StrideA dA,
            TB const* B, StrideB dB,
            TC      * C, StrideC dC)
{
  using namespace cute;

  int M = get<0>(shape_MNK);
  int N = get<1>(shape_MNK);
  int K = get<2>(shape_MNK);

  // Represent full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), dB); // (N,K) -- B^T view
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), dC); // (M,N)

  // Tile
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<16>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{}); // (BM,BK,k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{}); // (BN,BK,k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{}); // (BM,BN)

  // Shared memory (double-buffered for pipelined cp.async)
  __shared__ TA smemA[2][128*16];
  __shared__ TB smemB[2][128*16];
  Tensor sA0 = make_tensor(make_smem_ptr(smemA[0]), make_shape(Int<128>{}, Int<16>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA[1]), make_shape(Int<128>{}, Int<16>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB[0]), make_shape(Int<128>{}, Int<16>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB[1]), make_shape(Int<128>{}, Int<16>{}));
  // Thread layouts
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Copy atoms for asynchronous global->shared memory transfers (cp.async)
  using CopyAtomA = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<TA>, TA>;
  using CopyAtomB = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<TB>, TB>;
  // 256 threads = ThrLayout(32,8); each thread moves ValLayout(4,2) elements
  // 32*4 = 128 == BM/BN,  8*2 = 16 == BK  -> covers the whole (128,16) tile
  auto copyA = make_tiled_copy(CopyAtomA{},
                                make_layout(make_shape(Int<32>{}, Int<8>{})),
                                make_layout(make_shape(Int<4>{},  Int<2>{})));
  auto copyB = make_tiled_copy(CopyAtomB{},
                                make_layout(make_shape(Int<32>{}, Int<8>{})),
                                make_layout(make_shape(Int<4>{},  Int<2>{})));
  auto thr_copy_a = copyA.get_slice(threadIdx.x);
  Tensor tAgA = thr_copy_a.partition_S(gA);
  Tensor tAsA0 = thr_copy_a.partition_D(sA0);
  Tensor tAsA1 = thr_copy_a.partition_D(sA1);
  auto thr_copy_b = copyB.get_slice(threadIdx.x);
  Tensor tBgB = thr_copy_b.partition_S(gB);
  Tensor tBsB0 = thr_copy_b.partition_D(sB0);
  Tensor tBsB1 = thr_copy_b.partition_D(sB1);
  // Pipelined main loop over K with double-buffered shared memory
  int K_TILE_MAX = size<3>(tAgA);
  // Prologue: prefetch first tile into buffer 0
  copy(copyA, tAgA(_,_,_,0), tAsA0);
  copy(copyB, tBgB(_,_,_,0), tBsB0);
  cp_async_fence();
  int read_buf = 0;
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    cp_async_wait<0>();
    __syncthreads();
    int next_tile = k_tile + 1;
    int write_buf = read_buf ^ 1;
    if (next_tile < K_TILE_MAX) {
      if (write_buf == 0) {
        copy(copyA, tAgA(_,_,_,next_tile), tAsA0);
        copy(copyB, tBgB(_,_,_,next_tile), tBsB0);
      } else {
        copy(copyA, tAgA(_,_,_,next_tile), tAsA1);
        copy(copyB, tBgB(_,_,_,next_tile), tBsB1);
      }
    }
    cp_async_fence();
    if (read_buf == 0) {
      gemm(tCsA0, tCsB0, tCrC);
    } else {
      gemm(tCsA1, tCsB1, tCrC);
    }
    __syncthreads();
    read_buf = write_buf;
  }
  // Epilogue
  axpby(1.0f, tCrC, 0.0f, tCgC);
}

// Host wrapper
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  // A: (M,K) row-major, B: (K,N) row-major, C = A @ B : (M,N)
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K, "B.size(0) must equal K");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  // mA: shape (M,K), row-major -> stride (K,1)
  auto dA = make_stride(K, Int<1>{});
  // mB: shape (N,K) view of B (K,N) row-major -> stride (1,N)  (this is B^T view)
  auto dB = make_stride(Int<1>{}, N);
  // mC: shape (M,N), row-major -> stride (N,1)
  auto dC = make_stride(N, Int<1>{});

  auto shape_MNK = make_shape(M, N, K);

  dim3 dimBlock(256);
  dim3 dimGrid((M+127)/128, (N+127)/128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<<<dimGrid, dimBlock, 0, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_inline",
    cpp_sources=cute_cpp_decl,
    cuda_sources=cute_cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom CUTE-based tiled GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A.cuda(), B.cuda())

